.hero {
  background: linear-gradient(135deg, var(--color-primary-dark) 0%, var(--color-primary) 100%);
  color: var(--color-text-on-dark);
  padding: var(--spacing-2xl) var(--spacing-md);
  text-align: center;
  border-radius: var(--border-radius);
  margin-bottom: var(--spacing-2xl);
}

.hero h1 {
  color: var(--color-text-on-dark);
  margin-bottom: var(--spacing-md);
}

.hero p {
  font-size: 1.1rem;
  margin-bottom: var(--spacing-lg);
  color: var(--color-accent-light);
}

.section {
  padding: var(--spacing-xl) var(--spacing-md);
}

.section-title {
  text-align: center;
  margin-bottom: var(--spacing-xl);
}

.feature-list {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: var(--spacing-lg);
  margin: var(--spacing-lg) 0;
}

.feature-list li {
  list-style: none;
  padding-left: 2rem;
  position: relative;
}

.feature-list li:before {
  content: '✓';
  position: absolute;
  left: 0;
  color: var(--color-success);
  font-weight: bold;
  font-size: 1.25rem;
}

.testimonial {
  background-color: var(--color-bg-light);
  padding: var(--spacing-lg);
  border-left: 4px solid var(--color-primary-dark);
  border-radius: var(--border-radius);
  margin: var(--spacing-md) 0;
  font-style: italic;
}

.testimonial-author {
  font-weight: 600;
  font-style: normal;
  color: var(--color-text);
  margin-top: var(--spacing-sm);
}

.price {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--color-primary-dark);
  margin: var(--spacing-md) 0;
}

.badge {
  display: inline-block;
  background-color: var(--color-accent);
  color: var(--color-text);
  padding: 0.25rem 0.75rem;
  border-radius: 20px;
  font-size: 0.85rem;
  font-weight: 600;
  margin-right: var(--spacing-xs);
}

.main {
  min-height: calc(100vh - 200px);
}

@media (max-width: 600px) {
  .container {
    padding: 0 var(--spacing-sm);
  }

  .header .container {
    flex-direction: column;
    gap: var(--spacing-sm);
    min-height: auto;
  }

  .logo {
    width: 100%;
    text-align: center;
  }

  h1 {
    font-size: 1.5rem;
  }

  h2 {
    font-size: 1.25rem;
  }

  .hero {
    padding: var(--spacing-lg) var(--spacing-sm);
    margin-bottom: var(--spacing-lg);
  }

  .section {
    padding: var(--spacing-lg) var(--spacing-sm);
  }

  table {
    font-size: 0.85rem;
    margin: var(--spacing-md) 0;
  }

  th,
  td {
    padding: var(--spacing-sm);
  }

  .card-grid {
    grid-template-columns: 1fr;
    gap: var(--spacing-md);
  }

  .feature-list {
    grid-template-columns: 1fr;
    gap: var(--spacing-md);
  }

  button,
  .btn {
    width: 100%;
    padding: 1rem 0.75rem;
  }

  .testimonial {
    padding: var(--spacing-md);
  }

  .footer p {
    font-size: 0.9rem;
  }
}

@media (min-width: 601px) {
  .container {
    padding: 0 var(--spacing-lg);
  }

  .section {
    padding: var(--spacing-2xl) var(--spacing-md);
  }

  .feature-list {
    grid-template-columns: repeat(3, 1fr);
  }
}

pages.css:
.index-facilities {
  background-color: var(--color-bg-light);
  padding: var(--spacing-2xl) var(--spacing-md);
}

.index-memberships {
  padding: var(--spacing-2xl) var(--spacing-md);
}

.index-membership-intro {
  text-align: center;
  font-size: 1.1rem;
  color: var(--color-text-light);
  margin-bottom: var(--spacing-lg);
}

.index-table-wrapper {
  overflow-x: auto;
  margin-bottom: var(--spacing-2xl);
}

table {
  min-width: 700px;
}

.index-price {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--color-primary-dark);
}

.index-popular {
  background-color: var(--color-accent-light);
  font-weight: 600;
}

.index-popular:hover {
  background-color: #ffd966;
}

.index-plan-details {
  margin-top: var(--spacing-2xl);
}

.index-plan-details h3 {
  text-align: center;
  margin-bottom: var(--spacing-lg);
}

.index-plan-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: var(--spacing-lg);
  margin: var(--spacing-lg) 0;
}

.index-premium-card {
  position: relative;
  border: 2px solid var(--color-primary-dark);
  transform: scale(1.05);
  box-shadow: var(--shadow-lg);
}

.index-badge-top {
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background-color: var(--color-accent);
  color: var(--color-text);
  padding: 0.25rem 1rem;
  border-radius: 20px;
  font-weight: 700;
  font-size: 0.85rem;
  white-space: nowrap;
}

.index-plan-features {
  list-style: none;
  margin: var(--spacing-md) 0;
  padding: 0;
}

.index-plan-features li {
  padding: 0.5rem 0 0.5rem 1.75rem;
  position: relative;
  color: var(--color-text-light);
}

.index-plan-features li:before {
  content: '✓';
  position: absolute;
  left: 0;
  color: var(--color-success);
  font-weight: bold;
  font-size: 1.1rem;
}

.index-signup-btn {
  width: 100%;
  margin-top: var(--spacing-md);
}

.index-testimonials {
  background-color: var(--color-bg-light);
  padding: var(--spacing-2xl) var(--spacing-md);
}

.index-testimonials-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: var(--spacing-lg);
  margin-top: var(--spacing-lg);
}

.index-testimonials .testimonial {
  background-color: var(--color-bg);
}

.index-cta {
  background: linear-gradient(135deg, var(--color-primary-dark) 0%, var(--color-primary) 100%);
  color: var(--color-text-on-dark);
  padding: var(--spacing-2xl) var(--spacing-md);
  text-align: center;
  border-radius: var(--border-radius);
}

.index-cta h2 {
  color: var(--color-text-on-dark);
  margin-bottom: var(--spacing-md);
}

.index-cta p {
  font-size: 1.05rem;
  color: var(--color-accent-light);
  margin-bottom: var(--spacing-lg);
}

.index-cta-buttons {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-md);
  margin: var(--spacing-lg) 0;
  align-items: center;
}

.index-cta-note {
  font-size: 0.95rem;
  color: var(--color-accent-light);
  margin-top: var(--spacing-md);
}

@media (max-width: 600px) {
  .index-facilities {
    padding: var(--spacing-lg) var(--spacing-sm);
  }

  .index-memberships {
    padding: var(--spacing-lg) var(--spacing-sm);
  }

  .index-table-wrapper {
    margin-bottom: var(--spacing-lg);
  }

  table {
    min-width: 100%;
    font-size: 0.8rem;
  }

  th,
  td {
    padding: var(--spacing-xs);
  }

  .index-price {
    font-size: 1.1rem;
  }

  .index-premium-card {
    transform: scale(1);
  }

  .index-plan-grid {
    grid-template-columns: 1fr;
    gap: var(--spacing-md);
  }

  .index-signup-btn {
    width: 100%;
  }

  .index-testimonials {
    padding: var(--spacing-lg) var(--spacing-sm);
  }

  .index-testimonials-grid {
    grid-template-columns: 1fr;
    gap: var(--spacing-md);
  }

  .index-cta {
    padding: var(--spacing-lg) var(--spacing-sm);
  }

  .index-cta-buttons {
    flex-direction: column;
  }

  .index-cta-buttons .btn {
    width: 100%;
  }
}

@media (min-width: 601px) {
  .index-cta-buttons {
    justify-content: center;
    flex-direction: row;
  }

  .index-cta-buttons .btn {
    min-width: 200px;
  }
}
